target.css:
:root {
  --cream: #fdf6ec;
  --gold: #c9a84c;
  --gold-light: #f0dfa0;
  --dark: #1e1a14;
  --text-main: #3a3228;
  --text-muted: #8a7c6e;
  --section-bg: #ffffff;
  --featured-bg: #fdf3d8;
  --featured-border: #c9a84c;
  --border-light: #e8dece;
  --btn-bg: #1e1a14;
  --btn-text: #fdf6ec;
  --badge-bg: #c9a84c;
  --badge-text: #1e1a14;
  --star-color: #c9a84c;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.menu-card {
  background: var(--cream);
  border: 2px solid var(--gold);
  border-radius: 12px;
  width: 500px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.menu-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-light);
}

.hotel-star {
  font-size: 28px;
  color: var(--star-color);
  line-height: 1;
}

.header-text {
  flex: 1;
}

.menu-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--dark);
  letter-spacing: 0.04em;
}

.menu-subtitle {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

.room-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 13px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 20px;
}

.menu-sections {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.menu-section {
  background: var(--section-bg);
  border: 1px solid var(--border-light);
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-light);
}

.menu-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 8px;
  border-radius: 6px;
}

.menu-item.featured {
  background: var(--featured-bg);
  border: 1px solid var(--featured-border);
}

.item-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-main);
}

.item-price {
  font-size: 13px;
  font-weight: 700;
  color: var(--gold);
}

.menu-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 14px;
  border-top: 1px solid var(--border-light);
}

.footer-note {
  font-size: 11px;
  color: var(--text-muted);
  font-style: italic;
}

.order-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  padding: 8px 22px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
}

